wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8350000000409160)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load project header (legacy PL/SQL page process)'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_fy24  NUMBER;',
'  l_fy25  NUMBER;',
'  l_org   projects.org_code%TYPE;',
'BEGIN',
'  IF :P5_PROJECT_ID IS NULL THEN',
'    apex_error.add_error(',
'      p_message          => ''Select a project first.'',',
'      p_display_location => apex_error.c_inline_in_notification);',
'    RETURN;',
'  END IF;',
'',
'  SELECT p.name, p.state, NVL(o.name, p.district_name), p.org_code,',
'         p.fy2024_assumed + NVL(p.fy2024_iija, 0), p.fy2025_total',
'    INTO :P5_NAME, :P5_STATE, :P5_DISTRICT, l_org, l_fy24, l_fy25',
'    FROM projects p',
'    LEFT JOIN organizations o ON o.code = p.org_code',
'   WHERE p.project_id = :P5_PROJECT_ID;',
'',
'  :P5_FY24_TOTAL  := TO_CHAR(l_fy24, ''FML999G999G999G999'');',
'  :P5_FY25_BUDGET := TO_CHAR(l_fy25, ''FML999G999G999G999'');',
'  :P5_STATUS      := emt_legacy.project_status_label(l_fy24, l_fy25);',
'',
'  SELECT COUNT(*) INTO :P5_DISTRICT_PROJECTS FROM projects WHERE org_code = l_org;',
'',
'  SELECT LISTAGG(hazard || ''='' || cnt, ''; '') WITHIN GROUP (ORDER BY hazard)',
'    INTO :P5_HAZARD_MIX',
'    FROM (SELECT NVL(hazard, ''Undetermined'') AS hazard, COUNT(*) AS cnt',
'            FROM assets WHERE org_code = l_org',
'           GROUP BY NVL(hazard, ''Undetermined''));',
'',
'  apex_util.set_session_state(''P5_LAST_REFRESH'', TO_CHAR(SYSTIMESTAMP, ''YYYY-MM-DD HH24:MI:SS''));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    apex_error.add_error(',
'      p_message          => ''Project '' || :P5_PROJECT_ID || '' not found.'',',
'      p_display_location => apex_error.c_inline_in_notification);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8350000000409160
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8350000000409161)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Recalculate status'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_fy24 NUMBER;',
'  l_fy25 NUMBER;',
'BEGIN',
'  SELECT fy2024_assumed + NVL(fy2024_iija, 0), fy2025_total',
'    INTO l_fy24, l_fy25',
'    FROM projects WHERE project_id = :P5_PROJECT_ID;',
'  :P5_STATUS := emt_legacy.project_status_label(l_fy24, l_fy25);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8350000000409151)
,p_process_success_message=>'Status recalculated by emt_legacy.project_status_label.'
,p_internal_uid=>8350000000409161
);
end;
